const metrics = $input.first().json;

const dbSizeMB = Math.round((parseInt(metrics.db_size_bytes) || 0) / 1024 / 1024);
const activeQueries = parseInt(metrics.active_queries) || 0;
const idleConns = parseInt(metrics.idle_connections) || 0;
const longestQuery = parseFloat(metrics.longest_query_seconds) || 0;
const avgExecMs = Math.round(parseFloat(metrics.avg_execution_ms) || 0);
const executions1h = parseInt(metrics.executions_1h) || 0;

const issues = [];
let status = 'healthy';

if (longestQuery > 30) { issues.push(`Slow query running: ${longestQuery.toFixed(1)}s`); status = 'degraded'; }
if (longestQuery > 120) { status = 'critical'; }
if (activeQueries > 50) { issues.push(`High active queries: ${activeQueries}`); status = 'degraded'; }
if (idleConns > 150) { issues.push(`Too many idle connections: ${idleConns}`); }
if (avgExecMs > 5000) { issues.push(`Slow avg execution: ${avgExecMs}ms`); status = 'degraded'; }
if (dbSizeMB > 50000) { issues.push(`Database large: ${dbSizeMB}MB`); }

return [{ json: {
  status,
  db_size_mb: dbSizeMB,
  active_queries: activeQueries,
  idle_connections: idleConns,
  longest_query_sec: longestQuery,
  avg_execution_ms: avgExecMs,
  executions_1h: executions1h,
  issues,
  has_issues: issues.length > 0,
  checked_at: new Date().toISOString()
}}];

